func activityDotClass(eventType string) string {
	switch eventType {
	case model.EventPRMerged:
		return "bg-[hsl(270_70%_70%)]"
	case model.EventIssueOpened, model.EventPROpened:
		return "bg-success"
	case model.EventIssueClosed, model.EventPRClosed:
		return "bg-destructive"
	default:
		return "bg-muted-foreground"
	}
}

func eventVerb(eventType string) string {
	switch eventType {
	case model.EventPRMerged:
		return "merged"
	case model.EventPROpened:
		return "opened a pull request in"
	case model.EventPRClosed:
		return "closed a pull request in"
	case model.EventIssueOpened:
		return "opened an issue in"
	case model.EventIssueClosed:
		return "closed an issue in"
	default:
		return "pushed to"
	}
}

// Anything beyond a week falls back to an absolute date.
func formatRelative(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		m := int(d / time.Minute)
		if m == 1 {
			return "1 minute ago"
		}
		return strconv.Itoa(m) + " minutes ago"
	case d < 24*time.Hour:
		h := int(d / time.Hour)
		if h == 1 {
			return "1 hour ago"
		}
		return strconv.Itoa(h) + " hours ago"
	case d < 7*24*time.Hour:
		days := int(d / (24 * time.Hour))
		if days == 1 {
			return "1 day ago"
		}
		return strconv.Itoa(days) + " days ago"
	default:
		return t.Format("Jan 2, 2006")
	}
}

// Lossy: event types without a clear TimelineEntryKind fall through to TimelineEntryComment.
func eventTimelineKind(eventType string) components.TimelineEntryKind {
	switch eventType {
	case model.EventIssueClosed, model.EventPRClosed:
		return components.TimelineEntryClosed
	case model.EventPRMerged:
		return components.TimelineEntryMerged
	case model.EventIssueOpened, model.EventPROpened:
		return components.TimelineEntryOpened
	default:
		return components.TimelineEntryComment
	}
}

func eventTimelineDetail(ev model.Event) string {
	if ev.RepoName == "" {
		return ""
	}
	if ev.OwnerName == "" {
		return ev.RepoName
	}
	return fmt.Sprintf("%s/%s", ev.OwnerName, ev.RepoName)
}

func pluralize(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

type repoDropdownOption struct {
	Value string
	Label string
}

func heatmapCountLabel(total, year int) string {
	y := strconv.Itoa(year)
	switch {
	case total == 0:
		return "No commits in " + y
	case total == 1:
		return "1 commit in " + y
	default:
		return commaInt(total) + " commits in " + y
	}
}

// commaInt formats a non-negative integer with thousands separators.
func commaInt(n int) string {
	s := strconv.Itoa(n)
	out := ""
	for i, c := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			out += ","
		}
		out += string(c)
	}
	return out
}

func heatmapYearMenu(data view.HomeData) []repoMenuItem {
	items := make([]repoMenuItem, 0, len(data.HeatmapYears))
	for _, y := range data.HeatmapYears {
		items = append(items, repoMenuItem{
			Label:  strconv.Itoa(y),
			URL:    "/?year=" + strconv.Itoa(y),
			Active: y == data.HeatmapYear,
		})
	}
	return items
}

func repoSortOptions() []repoDropdownOption {
	return []repoDropdownOption{
		{"updated", "Last updated"},
		{"created", "Recently created"},
		{"name", "Name"},
	}
}

func repoFilterOptions() []repoDropdownOption {
	return []repoDropdownOption{
		{"all", "All"},
		{"sources", "Sources"},
		{"forks", "Forks"},
		{"templates", "Templates"},
	}
}

func repoSortLabel(sort string) string {
	switch sort {
	case "name":
		return "Name"
	case "created":
		return "Recently created"
	default:
		return "Last updated"
	}
}

func homeRepoURL(sort, filter string) string {
	q := "?"
	if sort != "" && sort != "updated" {
		q += "repo_sort=" + sort + "&"
	}
	if filter != "" && filter != "all" {
		q += "repo_filter=" + filter + "&"
	}
	if q == "?" {
		return "/"
	}
	return "/" + q[:len(q)-1]
}

// Returns a Tailwind color class for the language dot. Unknown languages get a neutral dot.
func languageDotClass(lang string) string {
	switch lang {
	case "Go":
		return "bg-cyan-400"
	case "Rust":
		return "bg-orange-400"
	case "TypeScript", "JavaScript":
		return "bg-yellow-400"
	case "Python":
		return "bg-blue-400"
	case "Ruby":
		return "bg-red-400"
	case "Java", "Kotlin":
		return "bg-orange-500"
	case "C", "C++":
		return "bg-blue-600"
	case "C#":
		return "bg-violet-500"
	case "Lua":
		return "bg-violet-400"
	case "Swift":
		return "bg-orange-300"
	case "Shell", "Bash":
		return "bg-green-400"
	case "HTML", "CSS":
		return "bg-pink-400"
	case "PHP":
		return "bg-indigo-400"
	case "Scala":
		return "bg-red-500"
	case "Elixir":
		return "bg-purple-400"
	case "Haskell":
		return "bg-violet-600"
	case "Dart":
		return "bg-sky-400"
	default:
		return "bg-muted-foreground/60"
	}
}

